# LMD GHOST: albero di blocchi, ultimo voto di ogni validatore, pesi = stake
parent = {
    "B1": None,
    "U2": "B1", "U3": "U2", "U4a": "U3", "U4b": "U3",          # ramo superiore
    "L2": "B1", "L3": "L2", "L4": "L3", "L5": "L4",            # ramo inferiore
}
children = {b: [] for b in parent}
for b, p in parent.items():
    if p:
        children[p].append(b)

def weight(block, latest, stake):
    """w(B) = somma dello stake dei validatori il cui ultimo voto è B o un suo discendente."""
    w = sum(stake[v] for v, b in latest.items() if b == block)
    return w + sum(weight(c, latest, stake) for c in children[block])

def lmd_ghost(root, latest, stake):
    head = root
    while children[head]:
        # pareggio risolto con il nome più "alto" (nella specifica: block root più alto)
        head = max(children[head], key=lambda c: (weight(c, latest, stake), c))
    return head

def depth(b):
    return 0 if parent[b] is None else 1 + depth(parent[b])

# voti che riproducono la figura della slide 41 (100 validatori da 32 ETH)
votes = {"U2": 10, "U3": 20, "U4a": 10, "U4b": 20, "L2": 10, "L5": 30}
latest, stake, i = {}, {}, 0
for block, n in votes.items():
    for _ in range(n):
        latest[f"v{i}"] = block; stake[f"v{i}"] = 32; i += 1

print({b: weight(b, latest, stake) // 32 for b in parent})
print("testa LMD GHOST:", lmd_ghost("B1", latest, stake))
print("testa catena più lunga:", max(parent, key=depth))

# LMD: 15 validatori che avevano votato U4b cambiano idea e votano L5 (conta solo l'ultimo voto)
moved = [v for v, b in latest.items() if b == "U4b"][:15]
for v in moved:
    latest[v] = "L5"
print("dopo 15 voti spostati:", lmd_ghost("B1", latest, stake),
      {b: weight(b, latest, stake) // 32 for b in ["U2", "L2"]})

